class HttpError extends Error {
  constructor(
    public readonly statusCode: number,
    message: string,
    options?: { cause?: unknown }
  ) {
    super(message, options);
    this.name = 'HttpError';
  }
}

class NotFoundError extends HttpError {
  constructor(public readonly resource: string, id: string) {
    super(404, `${resource} not found: ${id}`);
    this.name = 'NotFoundError';
  }
}

function getUser(id: string) {
  const user = db.find(id);
  if (!user) throw new NotFoundError('User', id);
  return user;
}

type AppError =
  | { kind: 'validation'; fields: Record<string, string> }
  | { kind: 'not-found'; resource: string; id: string }
  | { kind: 'conflict'; message: string };

type Result<T> = { ok: true; value: T } | { ok: false; error: AppError };

function updateEmail(userId: string, email: string): Result<void> {
  if (!email.includes('@')) {
    return { ok: false, error: { kind: 'validation', fields: { email: 'invalid' } } };
  }
  if (!db.exists(userId)) {
    return { ok: false, error: { kind: 'not-found', resource: 'User', id: userId } };
  }
  db.setEmail(userId, email);
  return { ok: true, value: undefined };
}

function errorMiddleware(err: unknown, _req: Request, res: Response, _next: NextFunction) {
  if (err instanceof HttpError) {
    return res.status(err.statusCode).json({ error: err.message });
  }
  if (err instanceof Error) {
    logger.error({ name: err.name, message: err.message, stack: err.stack, cause: err.cause });
    return res.status(500).json({ error: 'Internal server error' });
  }
  logger.error({ raw: err });
  res.status(500).json({ error: 'Internal server error' });
}

