// Safer for APIs:
type WireError = { code: 'NOT_FOUND'; resource: string; id: string };

function toWire(error: AppError): WireError {
  switch (error.kind) {
    case 'not-found':
      return { code: 'NOT_FOUND', resource: error.resource, id: error.id };
    // ...
    default:
      return { code: 'NOT_FOUND', resource: 'Unknown', id: '' }; // exhaustive in real code
  }
}
